def count_pentagons(n, acute_count):
    count = 0
    for x1 in range(1, n):
        for x2 in range(1, n - x1):
            for x3 in range(1, n - x1 - x2):
                for x4 in range(1, n - x1 - x2 - x3):
                    x5 = n - x1 - x2 - x3 - x4
                    if x5 >= 1:
                        sums = [x1+x2, x2+x3, x3+x4, x4+x5, x5+x1]
                        if sum(1 for s in sums if s > n/2) == acute_count:
                            count += 1
    return count * n // 5

print(f"n=100, one acute: {count_pentagons(100, 1)}")
print(f"n=100, zero acute: {count_pentagons(100, 0)}")
print(f"n=100, two acute: {count_pentagons(100, 2)}")

def count_hexagons(n, acute_count):
    count = 0
    for x1 in range(1, n):
        for x2 in range(1, n - x1):
            for x3 in range(1, n - x1 - x2):
                for x4 in range(1, n - x1 - x2 - x3):
                    for x5 in range(1, n - x1 - x2 - x3 - x4):
                        x6 = n - x1 - x2 - x3 - x4 - x5
                        if x6 >= 1:
                            sums = [x1+x2, x2+x3, x3+x4, x4+x5, x5+x6, x6+x1]
                            if sum(1 for s in sums if s > n/2) == acute_count:
                                count += 1
    return count * n // 6

